mapper.update:
UPDATE customer_tag
SET name = #{name},
    color = #{color},
    update_time = #{updateTime},
    update_user = #{updateUser}
WHERE id = #{id}

mapper.select:
SELECT id, name, color, organization_id, create_time, update_time, create_user, update_user
FROM customer_tag
WHERE id = #{id}

SELECT id, name, color, organization_id, create_time, update_time, create_user, update_user FROM customer_tag WHERE organization_id = #{organizationId}
AND name LIKE CONCAT('%', #{name}, '%')
ORDER BY create_time DESC

